// Client-side fallback formatter only — the real, unique card number
// is generated by the backend when the card is saved.
export function formatCardNumber(raw) {
  if (!raw) return "•••-•••-••••";
  return raw;
}

export function randomPreviewNumber() {
  const a = String(Math.floor(Math.random() * 1000)).padStart(3, "0");
  const b = String(Math.floor(Math.random() * 1000)).padStart(3, "0");
  const c = String(Math.floor(Math.random() * 10000)).padStart(4, "0");
  return `${a}-${b}-${c}`;
}
